import "@/components/audio-ui/plot/web";

const response = (hz: number, point: { x: number; y: number }) =>
  point.y * Math.exp(-(Math.log2(hz / point.x) ** 2));

type Curve = HTMLElement & { fn?: (x: number) => number };
type Grid = HTMLElement & {
  x?: { ticks: number[] };
  y?: { ticks: number[] };
};

/** Draws the plot into `element`, and returns what takes it away. A curve is a function, so it is set as a property. */
export function plotWebDemo(element: HTMLElement) {
  element.innerHTML = `
    <audio-ui-plot class="block rounded-lg border bg-card relative h-48 w-full touch-none select-none data-disabled:opacity-50" max-x="20000" max-y="12" min-x="20" min-y="-12" scale-x="log">
      <audio-ui-plot-grid class="text-muted-foreground rounded-[inherit] text-[10px] text-muted-foreground tabular-nums leading-none [&>svg]:overflow-hidden! [&>svg]:rounded-[inherit] [&_[data-part=line]]:stroke-border [&_[data-part=line][data-zero]]:stroke-foreground/30 [&_[data-part=label]]:z-1 [&_[data-part=label]]:px-0.5 [&_[data-part=label]]:[text-shadow:0_0_2px_var(--card),0_0_2px_var(--card),0_0_4px_var(--card)] [&_[data-part=label][data-axis=x]]:-translate-x-1/2 [&_[data-part=label][data-axis=x]]:bottom-1.5 [&_[data-part=label][data-axis=y]]:-translate-y-1/2 [&_[data-part=label][data-axis=y]]:left-2"></audio-ui-plot-grid>
      <div class="text-primary absolute inset-0 overflow-hidden! rounded-[inherit]">
        <audio-ui-plot-curve class="fill-primary/15 stroke-none" fill-to="0"></audio-ui-plot-curve>
        <audio-ui-plot-curve class="stroke-primary stroke-[1.5px] fill-none [stroke-linecap:round] [stroke-linejoin:round]"></audio-ui-plot-curve>
      </div>
      <audio-ui-plot-handle aria-label="Peak" class="rounded-full border-2 border-primary bg-background shadow-xs data-active:bg-primary transition-[box-shadow] duration-150 ease-out hover:ring-4 hover:ring-ring/30 focus-within:ring-4 focus-within:ring-ring/30 data-dragging:ring-4 data-dragging:ring-ring/30 motion-reduce:transition-none size-4 cursor-grab outline-none after:absolute after:-inset-2 pointer-coarse:after:-inset-3.5 data-dragging:cursor-grabbing data-disabled:pointer-events-none" handle="peak" value='{"x":1000,"y":6}'></audio-ui-plot-handle>
    </audio-ui-plot>`;
  let peak = { x: 1000, y: 6 };
  const plot = element.querySelector("audio-ui-plot");
  const handle = element.querySelector("audio-ui-plot-handle");
  const grid = element.querySelector("audio-ui-plot-grid") as Grid | null;
  const curves = [
    ...element.querySelectorAll("audio-ui-plot-curve"),
  ] as Curve[];
  const draw = () => {
    for (const curve of curves) {
      curve.fn = (hz) => response(hz, peak);
    }
  };
  if (grid) {
    grid.x = { ticks: [100, 1000, 10_000] };
    grid.y = { ticks: [-12, 0, 12] };
  }
  draw();
  const onInput = (event: Event) => {
    peak = (event as CustomEvent).detail.value;
    handle?.setAttribute("value", JSON.stringify(peak));
    draw();
  };
  plot?.addEventListener("input", onInput);
  return () => {
    plot?.removeEventListener("input", onInput);
    element.innerHTML = "";
  };
}
